// scripts/ble-master.mjs against a fake `gcloud` on PATH: the keyring goes to Secret Manager only
// through gcloud's standard input, never in an argument and never in the script's own output; a
// promotion needs the key in the deployed keyring and a retirement needs it no longer current
// there; gcloud runs with its logging turned down, and its error output is never passed on.
//
// Run with `npm test`. Nothing reaches the network: the fake gcloud keeps its state in a temporary
// directory, and every key is generated by the script under test or is a fixed fake value.

import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SCRIPT = path.join(ROOT, 'scripts/ble-master.mjs');
const SECRET = 'caddie-ble-master';
const PROJECT = 'test-project-1234';
// Written on the fake gcloud's error output when a test makes a call fail; it must never be shown.
const STDERR_CANARY = 'stderr-canary-request-body';

// The fake gcloud: a Node script that records every call's arguments and the CLOUDSDK_ settings it
// ran with, and answers the calls the script makes from a JSON state file.
const FAKE_GCLOUD = `#!/usr/bin/env node
const fs = require('node:fs');
const file = process.env.FAKE_GCLOUD_STATE;
const state = JSON.parse(fs.readFileSync(file, 'utf8'));
const argv = process.argv.slice(2);
const env = Object.fromEntries(Object.entries(process.env).filter(([k]) => k.startsWith('CLOUDSDK_')));
state.calls.push({ argv, env });
const save = () => fs.writeFileSync(file, JSON.stringify(state));
const done = (code, out = '') => { save(); if (out) process.stdout.write(out); process.exit(code); };
const has = (...words) => words.every((w, i) => argv[i] === w);
if (state.failOn && argv.join(' ').includes(state.failOn)) { save(); process.stderr.write('${STDERR_CANARY}'); process.exit(7); }
if (has('secrets', 'describe')) done(state.exists ? 0 : 1, state.exists ? 'projects/p/secrets/${SECRET}' : '');
if (has('secrets', 'create')) { state.exists = true; done(0); }
if (has('secrets', 'versions', 'list')) {
  const enabled = state.versions.filter((v) => v.enabled);
  done(0, enabled.length ? 'projects/p/secrets/${SECRET}/versions/' + enabled[enabled.length - 1].id + '\\n' : '');
}
if (has('secrets', 'versions', 'access')) {
  const v = state.versions.find((x) => x.id === argv[3]);
  done(v ? 0 : 1, v ? v.payload : '');
}
if (has('secrets', 'versions', 'add')) {
  const payload = fs.readFileSync(0, 'utf8');
  state.versions.push({ id: String(state.versions.length + 1), enabled: true, payload });
  done(0);
}
if (has('run', 'services', 'describe')) {
  const env = state.deployed === null ? [] : [{ name: 'BLE_MASTER_KEYRING', valueFrom: { secretKeyRef: { name: '${SECRET}', key: state.deployed } } }];
  const rev = 'conference-caddie-00042-abc';
  done(0, JSON.stringify({
    spec: { template: { spec: { containers: [{ env: [{ name: 'ES_INDEX', value: 'caddie-talks' }, ...env] }] } } },
    status: { latestReadyRevisionName: rev, latestCreatedRevisionName: state.ready === false ? 'conference-caddie-00043-new' : rev, traffic: [{ revisionName: rev, percent: 100, latestRevision: true }] },
  }));
}
done(9);
`;

let dir;
let stateFile;
before(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'ble-master-test-'));
  fs.writeFileSync(path.join(dir, 'gcloud'), FAKE_GCLOUD, { mode: 0o755 });
  stateFile = path.join(dir, 'state.json');
});
after(() => fs.rmSync(dir, { recursive: true, force: true }));

const reset = (over = {}) => fs.writeFileSync(stateFile, JSON.stringify({ exists: false, versions: [], deployed: null, calls: [], ...over }));
const state = () => JSON.parse(fs.readFileSync(stateFile, 'utf8'));
const set = (over) => fs.writeFileSync(stateFile, JSON.stringify({ ...state(), ...over }));

function run(...args) {
  const r = spawnSync(process.execPath, [SCRIPT, ...args, '--project', PROJECT], {
    env: { PATH: `${dir}${path.delimiter}${path.dirname(process.execPath)}${path.delimiter}/usr/bin:/bin`, FAKE_GCLOUD_STATE: stateFile },
    encoding: 'utf8',
    timeout: 30_000,
  });
  return { status: r.status, out: `${r.stdout}${r.stderr}` };
}

// Every secret value the store has ever held.
const secretsSeen = () => state().versions.flatMap((v) => Object.values(JSON.parse(v.payload).keys));
const latest = () => JSON.parse(state().versions.at(-1).payload);

// What no argument, no environment value and no output may ever contain.
function assertNoSecretLeaks(out) {
  const secrets = secretsSeen();
  assert.ok(secrets.length > 0);
  for (const call of state().calls) {
    for (const secret of secrets) assert.ok(!call.argv.join(' ').includes(secret), `a secret went into the arguments of gcloud ${call.argv.slice(0, 3).join(' ')}`);
  }
  for (const secret of secrets) assert.ok(!out.includes(secret), 'a secret was printed');
  assert.ok(!out.includes(STDERR_CANARY), 'gcloud\'s error output was passed on');
  for (const call of state().calls) {
    assert.deepEqual(call.env, { CLOUDSDK_CORE_LOG_HTTP: 'false', CLOUDSDK_CORE_VERBOSITY: 'error', CLOUDSDK_CORE_DISABLE_FILE_LOGGING: 'true' });
    assert.equal(call.argv[call.argv.indexOf('--project') + 1], PROJECT);
  }
}

test('init, add-next, promote and retire, each written only through standard input', () => {
  reset();
  const init = run('--init');
  assert.equal(init.status, 0, init.out);
  assert.equal(state().versions.length, 1);
  const first = latest();
  const [oldId] = Object.keys(first.keys);
  assert.equal(first.current, oldId);
  assert.equal(Buffer.from(first.keys[oldId], 'base64url').length, 32);
  assert.match(init.out, new RegExp(`${oldId} \\(current\\)`));
  const adds = state().calls.filter((c) => c.argv.slice(0, 3).join(' ') === 'secrets versions add');
  assert.equal(adds.length, 1);
  assert.ok(adds[0].argv.includes('--data-file=-'), 'the payload is read from standard input');
  assertNoSecretLeaks(init.out);
  assert.equal(run('--init').status, 1, 'a second init is refused');

  set({ deployed: '1' });
  const add = run('--add-next');
  assert.equal(add.status, 0, add.out);
  const second = latest();
  const newId = Object.keys(second.keys).find((id) => id !== oldId);
  assert.equal(second.current, oldId, 'the new key is not current yet');
  assert.equal(second.keys[oldId], first.keys[oldId], 'the old key is kept as it was');

  const early = run('--promote', newId);
  assert.notEqual(early.status, 0, 'promoting a key the service does not hold yet is refused');
  assert.match(early.out, /does not hold key/);
  assert.equal(state().versions.length, 2, 'and writes nothing');

  set({ deployed: '2' });
  const promote = run('--promote', newId);
  assert.equal(promote.status, 0, promote.out);
  assert.equal(latest().current, newId);

  const retireEarly = run('--retire', oldId);
  assert.notEqual(retireEarly.status, 0, 'retiring the key that is still current on the service is refused');
  assert.match(retireEarly.out, /still current on/);
  assert.equal(state().versions.length, 3);
  assert.notEqual(run('--retire', newId).status, 0, 'the current key cannot be retired');

  set({ deployed: '3' });
  const retire = run('--retire', oldId);
  assert.equal(retire.status, 0, retire.out);
  assert.deepEqual(Object.keys(latest().keys), [newId]);

  const status = run('--status');
  assert.equal(status.status, 0, status.out);
  assert.match(status.out, new RegExp(`latest version 4: ${newId} \\(current\\)`));
  assert.match(status.out, new RegExp(`version 3: ${newId} \\(current\\), ${oldId}|version 3: ${oldId}, ${newId} \\(current\\)`));
  assertNoSecretLeaks([init, add, early, promote, retireEarly, retire, status].map((r) => r.out).join('\n'));
});

test('a service that is not ready, or mounts the keyring as "latest", refuses a promotion', () => {
  reset();
  assert.equal(run('--init').status, 0);
  set({ deployed: '1' });
  assert.equal(run('--add-next').status, 0);
  const newId = Object.keys(latest().keys).find((id) => id !== latest().current);
  set({ deployed: '2', ready: false });
  const notReady = run('--promote', newId);
  assert.notEqual(notReady.status, 0);
  assert.match(notReady.out, /not ready/);
  set({ ready: true, deployed: 'latest' });
  const unpinned = run('--promote', newId);
  assert.notEqual(unpinned.status, 0);
  assert.match(unpinned.out, /not a pinned version/);
  assert.equal(state().versions.length, 2, 'nothing was written');
});

test('a failed gcloud call prints the step and the exit code, never gcloud\'s own output', () => {
  reset();
  assert.equal(run('--init').status, 0);
  set({ failOn: 'versions add' });
  const r = run('--add-next');
  assert.equal(r.status, 1);
  assert.match(r.out, /Adding a version to caddie-ble-master failed \(gcloud exited with 7\)/);
  assertNoSecretLeaks(r.out);
});
